```ts
import { Effect } from "effect"

const program = Effect.gen(function*() {
  yield* Effect.logDebug("Debug mode enabled")

  const userInput = { name: "Alice", age: 30 }
  yield* Effect.logDebug("Processing user input:", userInput)

