})
```

Removes an edge from a mutable graph.

**Example** (Removing an edge)

```ts
import { Graph } from "effect"

const result = Graph.mutate(Graph.directed<string, number>(), (mutable) => {
  const nodeA = Graph.addNode(mutable, "Node A")
