description:
Creates a `LayerMap` that dynamically provides resources based on a key.

**Example** (Creating a layer map)

```ts
import { Context, Effect, Layer, LayerMap } from "effect"

// Define a service key
const DatabaseService = Context.Service<{
  readonly query: (sql: string) => Effect.Effect<string>
}>("Database")

// Create a LayerMap that provides different database configurations
const program = Effect.gen(function*() {
  const layerMap = yield* LayerMap.make(
    (env: string) =>
      Layer.succeed(DatabaseService)({
        query: Effect.fn("DatabaseService.query")((sql) => Effect.succeed(`${env}: ${sql}`))
      }),
    { idleTimeToLive: "5 seconds" }
  )

  // Get a layer for a specific environment
  const devLayer = layerMap.get("development")

  // Use the layer to provide the service
  const result = yield* Effect.provide(
    Effect.gen(function*() {
      const db = yield* DatabaseService
      return yield* db.query("SELECT * FROM users")
    }),
    devLayer
  )

  console.log(result) // "development: SELECT * FROM users"
})
```

Creates a `LayerMap` from a record of predefined layers.

**Details**

The record keys become the keys accepted by the returned `LayerMap`, and the
record values are the layers built for those keys.

**Example** (Creating a layer map from a record)

```ts
import { Context, Effect, Layer, LayerMap } from "effect"

// Define service keys
const DevDatabase = Context.Service<{
  readonly query: (sql: string) => Effect.Effect<string>
}>("DevDatabase")

const ProdDatabase = Context.Service<{
  readonly query: (sql: string) => Effect.Effect<string>
}>("ProdDatabase")

// Create predefined layers
const layers = {
  development: Layer.succeed(DevDatabase)({
    query: Effect.fn("DevDatabase.query")((sql) => Effect.succeed(`DEV: ${sql}`))
  }),
  production: Layer.succeed(ProdDatabase)({
    query: Effect.fn("ProdDatabase.query")((sql) => Effect.succeed(`PROD: ${sql}`))
  })
} as const

// Create a LayerMap from the record
const program = Effect.gen(function*() {
  const layerMap = yield* LayerMap.fromRecord(layers, {
    idleTimeToLive: "10 seconds"
  })

  // Get layers by key
  const devLayer = layerMap.get("development")
  const prodLayer = layerMap.get("production")

  console.log("LayerMap created from record")
})
```

Create a `LayerMap` service that provides a dynamic set of resources based on
a key.

**Example** (Defining a layer map service)

```ts
import { Console, Context, Effect, Layer, LayerMap } from "effect"

// Define a service key
const Greeter = Context.Service<{
  readonly greet: Effect.Effect<string>
}>("Greeter")

// Create a service that wraps a LayerMap
class GreeterMap extends LayerMap.Service<GreeterMap>()("GreeterMap", {
  // Define the lookup function for the layer map
  lookup: (name: string) =>
    Layer.succeed(Greeter)({
      greet: Effect.succeed(`Hello, ${name}!`)
    }),

  // If a layer is not used for a certain amount of time, it can be removed
  idleTimeToLive: "5 seconds"
}) {}

// Usage
const program = Effect.gen(function*() {
  // Access and use the Greeter service
  const greeter = yield* Greeter
  yield* Console.log(yield* greeter.greet)
}).pipe(
  // Use the GreeterMap service to provide a variant of the Greeter service
  Effect.provide(GreeterMap.get("John"))
).pipe(
  // Provide the GreeterMap layer
  Effect.provide(GreeterMap.layer)
)
```

A scoped, keyed map of layer-built service contexts.

**Details**

A `LayerMap` builds resources for a key on demand, exposes them as a `Layer`
or scoped `Context`, and can invalidate cached resources for a key.

**Example** (Managing keyed layers)

```ts
import { Context, Effect, Layer, LayerMap } from "effect"

// Define a service key
const DatabaseService = Context.Service<{
  readonly query: (sql: string) => Effect.Effect<string>
}>("Database")

// Create a LayerMap that provides different database configurations
const createDatabaseLayerMap = LayerMap.make((env: string) =>
  Layer.succeed(DatabaseService)({
    query: Effect.fn("DatabaseService.query")((sql) => Effect.succeed(`${env}: ${sql}`))
  })
)

// Use the LayerMap
const program = Effect.gen(function*() {
  const layerMap = yield* createDatabaseLayerMap

  // Get a layer for a specific environment
  const devLayer = layerMap.get("development")

  // Get context directly
  const context = yield* layerMap.contextEffect("production")

  // Invalidate a cached layer
  yield* layerMap.invalidate("development")
})
```

signature:
export interface LayerMap<in out K, in out I, in out E = never> {
  readonly [TypeId]: typeof TypeId

  /**
   * The internal RcMap that stores the resources.
   */
  readonly rcMap: RcMap.RcMap<K, Context.Context<I>, E>

  /**
   * Retrieves a Layer for the resources associated with the key.
   */
  get(key: K): Layer.Layer<I, E>

  /**
   * Retrieves the context associated with the key.
   */
  contextEffect(key: K): Effect.Effect<Context.Context<I>, E, Scope.Scope>

  /**
   * Invalidates the resource associated with the key.
   */
  invalidate(key: K): Effect.Effect<void>
}

description:
Creates a `LayerRef` from a `Layer`.

**When to use**

Use when you have one layer-built resource that should be shared, optionally
kept alive while idle, and refreshed on demand.

**Details**

The layer is built lazily on first use unless `preload` is `true`.
`idleTimeToLive` keeps the context cached after it stops being used, and
`invalidationSchedule` can periodically invalidate it. When `preload` is
`true`, scheduled invalidation also reacquires the context.

**Gotchas**

Invalidation does not revoke contexts already borrowed by active scopes; those
contexts remain usable until their scopes close.

**Example** (Sharing one layer-built service)

```ts
import { Context, Effect, Layer, LayerRef } from "effect"

class Database extends Context.Service<Database, {
  readonly query: Effect.Effect<string>
}>()("Database") {}

const databaseLayer = Layer.succeed(Database, {
  query: Effect.succeed("result")
})

const query = Effect.gen(function*() {
  const database = yield* Database
  return yield* database.query
})

const program = Effect.scoped(
  Effect.gen(function*() {
    const ref = yield* LayerRef.make(databaseLayer, {
      idleTimeToLive: "5 seconds"
    })

    const result = yield* Effect.provide(query, ref.get)

    yield* ref.invalidate

    return result
  })
)
```

Creates a service class for a `LayerRef`.

**When to use**

Use when you want to name a shared layer reference as an application service
and expose static helpers for providing, retrieving, and invalidating it.

**Details**

The returned class is a `Context.Service` whose value is a `LayerRef`. It also
includes `.layer`, `.layerNoDeps`, `.get`, `.contextEffect`, and `.invalidate`
helpers so callers do not need to access the `LayerRef` value directly.

**Example** (Defining a refreshable service)

```ts
import { Context, Effect, Layer, LayerRef } from "effect"

class Database extends Context.Service<Database, {
  readonly query: Effect.Effect<string>
}>()("Database") {}

const databaseLayer = Layer.succeed(Database, {
  query: Effect.succeed("result")
})

class DatabaseRef extends LayerRef.Service<DatabaseRef>()("DatabaseRef", {
  layer: databaseLayer,
  preload: true
}) {}

const program = Effect.gen(function*() {
  const database = yield* Database
  return yield* database.query
}).pipe(
  Effect.provide(DatabaseRef.get),
  Effect.provide(DatabaseRef.layer)
)
```

Context reference containing the active loggers for the current fiber.

**Details**

By default this set includes the default logger and the tracer logger.
Providing `Logger.layer` replaces or merges with this set depending on its
options.

**Example** (Accessing current loggers)

```ts
import { Effect, Logger } from "effect"

// Access current loggers from fiber context
const program = Effect.gen(function*() {
  const currentLoggers = yield* Effect.service(Logger.CurrentLoggers)
  console.log(`Number of active loggers: ${currentLoggers.size}`)

  // Add a custom logger to the set
  const customLogger = Logger.make((options) => {
    console.log(`Custom: ${options.message}`)
  })

  yield* Effect.log("Hello from custom logger").pipe(
    Effect.provide(Logger.layer([customLogger]))
  )
})
```

Transforms the output of a `Logger` using the provided function.

**When to use**

Use when an existing logger's output should be transformed without recreating the
logging logic.

**Example** (Transforming logger output)

```ts
import { Logger } from "effect"

// Create a logger that outputs objects
const structuredLogger = Logger.make((options) => ({
  level: options.logLevel,
  message: options.message,
  timestamp: options.date.toISOString()
}))

// Transform the output to JSON strings
const jsonStringLogger = Logger.map(
  structuredLogger,
  (output) => JSON.stringify(output)
)

// Transform to uppercase messages
const uppercaseLogger = Logger.map(
  structuredLogger,
  (output) => ({ ...output, message: String(output.message).toUpperCase() })
)
```

Creates a new `Logger` from a log function.

**Details**

The log function receives an options object containing the message, log level,
cause, fiber information, and timestamp, and should return the desired output.

**Example** (Creating loggers from functions)

```ts
import { Effect, Logger, References } from "effect"

// Simple text logger
const textLogger = Logger.make((options) =>
  `${options.date.toISOString()} [${options.logLevel}] ${options.message}`
)

// Structured object logger
const objectLogger = Logger.make((options) => ({
  timestamp: options.date.toISOString(),
  level: options.logLevel,
  message: options.message,
  fiberId: options.fiber.id,
  annotations: options.fiber.getRef(References.CurrentLogAnnotations)
}))

// Custom filtering logger
const filteredLogger = Logger.make((options) => {
  if (options.logLevel === "Debug") {
    return // Skip debug messages
  }
  return `${options.logLevel}: ${options.message}`
})

const program = Effect.log("Hello World").pipe(
  Effect.provide(Logger.layer([textLogger]))
)
```

The default logging implementation used by the Effect runtime.

**Example** (Referencing the default logger)

```ts
import { Effect, Logger } from "effect"

// Use the default logger (automatically used by Effect runtime)
const program = Effect.gen(function*() {
  yield* Effect.log("This uses the default logger")
  yield* Effect.logInfo("Info message")
  yield* Effect.logError("Error message")
})

// Explicitly use the default logger
const withDefaultLogger = Effect.log("Explicit default").pipe(
  Effect.provide(Logger.layer([Logger.defaultLogger]))
)

// Compare with custom logger
const customLogger = Logger.make((options) => {
  console.log(`CUSTOM: ${options.message}`)
})
```

A `Logger` which outputs logs as a string.

**Details**

For example, a simple log entry is rendered as
`timestamp=2025-01-03T14:22:47.570Z level=INFO fiber=#1 message=hello`.

**Example** (Formatting logs as simple strings)

```ts
import { Effect, Logger } from "effect"

// Use the simple format logger
const simpleLoggerProgram = Effect.log("Hello Simple Format").pipe(
  Effect.provide(Logger.layer([Logger.formatSimple]))
)

// Combine with console output
const consoleSimpleLogger = Logger.withConsoleLog(Logger.formatSimple)

const program = Effect.gen(function*() {
  yield* Effect.log("Application started")
  yield* Effect.logInfo("Processing data")
  yield* Effect.logWarning("Memory usage high")
}).pipe(
  Effect.provide(Logger.layer([consoleSimpleLogger]))
)
```

A `Logger` which outputs logs using the [logfmt](https://brandur.org/logfmt)
style.

**Details**

For example, a logfmt entry is rendered as
`timestamp=2025-01-03T14:22:47.570Z level=INFO fiber=#1 message=hello`.

**Example** (Formatting logs as logfmt)

```ts
import { Effect, Logger } from "effect"

// Use the logfmt format logger
const logfmtLoggerProgram = Effect.log("Hello LogFmt Format").pipe(
  Effect.provide(Logger.layer([Logger.formatLogFmt]))
)

// Perfect for structured logging systems
const structuredProgram = Effect.gen(function*() {
  yield* Effect.log("User login", { userId: 123, method: "OAuth" })
  yield* Effect.logInfo("Request processed", {
    duration: 45,
    status: "success"
  })
}).pipe(
  Effect.provide(Logger.layer([Logger.withConsoleLog(Logger.formatLogFmt)]))
)

// Good for log aggregation systems like Splunk, ELK
const productionLogger = Logger.formatLogFmt
```

A `Logger` which outputs logs using a structured format.

**Details**

For example, a structured entry can contain `message: [ "hello" ]`,
`level: "INFO"`, `timestamp: "2025-01-03T14:25:39.666Z"`,
`annotations: { key: "value" }`, `spans: { label: 0 }`, and
`fiberId: "#1"`.

**Example** (Formatting logs as structured objects)

```ts
import { Effect, Logger } from "effect"

// Use the structured format logger
const structuredLoggerProgram = Effect.log("Hello Structured Format").pipe(
  Effect.provide(Logger.layer([Logger.formatStructured]))
)

// Perfect for JSON processing and analytics
const analyticsProgram = Effect.gen(function*() {
  yield* Effect.log("User action", { action: "click", element: "button" })
  yield* Effect.logInfo("API call", { endpoint: "/users", duration: 150 })
}).pipe(
  Effect.annotateLogs("sessionId", "abc123"),
  Effect.withLogSpan("request"),
  Effect.provide(Logger.layer([Logger.formatStructured]))
)

// Process structured output
const processingLogger = Logger.map(Logger.formatStructured, (output) => {
  // Process the structured object
  const enhanced = { ...output, processed: true }
  return enhanced
})
```

A `Logger` which outputs logs using a structured format serialized as JSON
on a single line.

**Details**

For example, a JSON entry can render as `{"message":["hello"],"level":"INFO",
"timestamp":"2025-01-03T14:28:57.508Z","annotations":{"key":"value"},
"spans":{"label":0},"fiberId":"#1"}`.

**Example** (Formatting logs as JSON)

```ts
import { Effect, Logger } from "effect"

// Use the JSON format logger
const jsonLoggerProgram = Effect.log("Hello JSON Format").pipe(
  Effect.provide(Logger.layer([Logger.formatJson]))
)

// Perfect for log aggregation and processing systems
const productionProgram = Effect.gen(function*() {
  yield* Effect.log("Server started", { port: 3000, env: "production" })
  yield* Effect.logInfo("Request received", {
    method: "GET",
    path: "/api/users"
  })
  yield* Effect.logError("Database error", { error: "Connection timeout" })
}).pipe(
  Effect.annotateLogs("service", "api-server"),
  Effect.withLogSpan("request-processing"),
  Effect.provide(Logger.layer([Logger.formatJson]))
)

// Adapt the JSON string before giving it to an output sink
const envelopedJsonLogger = Logger.map(
  Logger.formatJson,
  (jsonString) => `{"service":"api-server","entry":${jsonString}}`
)

const envelopedConsoleLogger = Logger.withConsoleLog(envelopedJsonLogger)
```

Creates a scoped logger that batches the output of another logger.

**Details**

The returned effect starts a scoped background process that periodically
passes buffered outputs to `flush`. When the scope closes, the background
process is interrupted and any remaining buffered entries are flushed.

**Example** (Batching logger output)

```ts
import { Duration, Effect, Logger } from "effect"

// Create a batched logger that flushes every 5 seconds
const batchedLogger = Logger.batched(Logger.formatJson, {
  window: Duration.seconds(5),
  flush: (messages) =>
    Effect.sync(() => {
      console.log(`Flushing ${messages.length} log entries:`)
      messages.forEach((msg, i) => console.log(`${i + 1}. ${msg}`))
    })
})

const program = Effect.gen(function*() {
  const logger = yield* batchedLogger

  yield* Effect.provide(
    Effect.all([
      Effect.log("Event 1"),
      Effect.log("Event 2"),
      Effect.log("Event 3"),
      Effect.sleep(Duration.seconds(6)), // Trigger flush
      Effect.log("Event 4")
    ]),
    Logger.layer([logger])
  )
})

// Remote batch logging example
const remoteBatchLogger = Logger.batched(Logger.formatStructured, {
  window: Duration.seconds(10),
  flush: (entries) =>
    Effect.sync(() => {
      // Send batch to remote logging service
      console.log(`Sending ${entries.length} log entries to remote service`)
    })
})
```

A `Logger` which outputs logs in a "pretty" format and writes them to the
console.

**Details**

For example, pretty output can render as
`[09:37:17.579] INFO (#1) label=0ms: hello` followed by an annotation line
such as `key: value`.

**Example** (Logging with pretty console output)

```ts
import { Effect, Logger } from "effect"

// Use the pretty console logger with default settings
const basicPretty = Effect.log("Hello Pretty Format").pipe(
  Effect.provide(Logger.layer([Logger.consolePretty()]))
)

// Configure pretty logger options
const customPretty = Logger.consolePretty({
  colors: true,
  stderr: false,
  mode: "tty",
  formatDate: (date) => date.toLocaleTimeString()
})

// Perfect for development environment
const developmentProgram = Effect.gen(function*() {
  yield* Effect.log("Application starting")
  yield* Effect.logInfo("Database connected")
  yield* Effect.logWarning("High memory usage detected")
}).pipe(
  Effect.annotateLogs("environment", "development"),
  Effect.withLogSpan("startup"),
  Effect.provide(Logger.layer([customPretty]))
)

// Disable colors for CI/CD environments
const ciLogger = Logger.consolePretty({ colors: false })
```

A `Logger` which outputs logs using the [logfmt](https://brandur.org/logfmt)
style and writes them to the console.

**Details**

For example, a console logfmt entry is rendered as
`timestamp=2025-01-03T14:22:47.570Z level=INFO fiber=#1 message=info`.

**Example** (Logging logfmt output to the console)

```ts
import { Effect, Logger } from "effect"

// Use the console logfmt logger
const logfmtProgram = Effect.log("Hello LogFmt Console").pipe(
  Effect.provide(Logger.layer([Logger.consoleLogFmt]))
)

// Great for production environments
const productionProgram = Effect.gen(function*() {
  yield* Effect.log("Server started", { port: 8080, version: "1.0.0" })
  yield* Effect.logInfo("Request processed", { userId: 123, duration: 45 })
  yield* Effect.logError("Validation failed", {
    field: "email",
    value: "invalid"
  })
}).pipe(
  Effect.annotateLogs("service", "api"),
  Effect.withLogSpan("request-handler"),
  Effect.provide(Logger.layer([Logger.consoleLogFmt]))
)

// Combine with other loggers
const multiLoggerLive = Logger.layer([
  Logger.consoleLogFmt,
  Logger.consolePretty()
])
```

A `Logger` which outputs logs using a structured format and writes them to
the console.

**Details**

For example, console structured output can contain
`message: [ "info", "message" ]`, `level: "INFO"`,
`timestamp: "2025-01-03T14:25:39.666Z"`,
`annotations: { key: "value" }`, `spans: { label: 0 }`, and
`fiberId: "#1"`.

**Example** (Logging structured output to the console)

```ts
import { Effect, Logger } from "effect"

// Use the console structured logger
const structuredProgram = Effect.log("Hello Structured Console").pipe(
  Effect.provide(Logger.layer([Logger.consoleStructured]))
)

// Perfect for development debugging
const debugProgram = Effect.gen(function*() {
  yield* Effect.log("User event", {
    userId: 123,
    action: "login",
    ip: "192.168.1.1"
  })
  yield* Effect.logInfo("API call", {
    endpoint: "/users",
    method: "GET",
    duration: 120
  })
}).pipe(
  Effect.annotateLogs("requestId", "req-123"),
  Effect.withLogSpan("authentication"),
  Effect.provide(Logger.layer([Logger.consoleStructured]))
)

// Easy to parse and inspect object structure
const inspectionProgram = Effect.gen(function*() {
  yield* Effect.log("Complex data", {
    user: { id: 1, name: "John" },
    metadata: { source: "api", version: 2 }
  })
}).pipe(
  Effect.provide(Logger.layer([Logger.consoleStructured]))
)
```

A `Logger` which outputs logs using a structured format serialized as JSON
on a single line and writes them to the console.

**Details**

For example, console JSON output can render as
`{"message":["hello"],"level":"INFO","timestamp":"2025-01-03T14:28:57.508Z",
"annotations":{"key":"value"},"spans":{"label":0},"fiberId":"#1"}`.

**Example** (Logging JSON output to the console)

```ts
import { Effect, Logger } from "effect"

// Use the console JSON logger
const jsonProgram = Effect.log("Hello JSON Console").pipe(
  Effect.provide(Logger.layer([Logger.consoleJson]))
)

// Perfect for production logging and log aggregation
const productionProgram = Effect.gen(function*() {
  yield* Effect.log("Server started", { port: 3000, env: "production" })
  yield* Effect.logInfo("Request", {
    method: "POST",
    url: "/api/users",
    body: { name: "Alice" }
  })
  yield* Effect.logError("Database error", {
    error: "Connection timeout",
    retryCount: 3
  })
}).pipe(
  Effect.annotateLogs("service", "user-api"),
  Effect.annotateLogs("version", "1.2.3"),
  Effect.withLogSpan("request-processing"),
  Effect.provide(Logger.layer([Logger.consoleJson]))
)

// Easy to pipe to log aggregation services
const productionSetup = Logger.layer([
  Logger.consoleJson, // For stdout JSON logs
  Logger.consolePretty() // For local debugging
])

// Ideal for containerized environments (Docker, Kubernetes)
const containerProgram = Effect.log("Container ready", {
  containerId: "abc123",
  image: "myapp:latest"
}).pipe(
  Effect.provide(Logger.layer([Logger.consoleJson]))
)
```

Creates a scoped logger that writes string logger output to a file.

**Details**

The returned effect requires `FileSystem` and `Scope`. The file logger batches
string output, writes each batch to the specified path, and flushes remaining
entries when the scope closes.

**Example** (Writing JSON logs to a file)

```ts
import { Effect, Layer, Logger } from "effect"
import { NodeFileSystem, NodeRuntime } from "@effect/platform-node"

const fileLogger = Logger.formatJson.pipe(
  Logger.toFile("/tmp/log.txt")
)
const LoggerLive = Logger.layer([fileLogger]).pipe(
  Layer.provide(NodeFileSystem.layer)
)

Effect.log("a").pipe(
  Effect.andThen(Effect.log("b")),
  Effect.andThen(Effect.log("c")),
  Effect.provide(LoggerLive),
  NodeRuntime.runMain
)
```

**Example** (Writing logs to files)

```ts
import { Duration, Effect, Logger } from "effect"
import { NodeFileSystem } from "@effect/platform-node"

// Basic file logging. The scope keeps the file open while logs are emitted
// and flushes pending entries when it closes.
const basicFileLogger = Effect.scoped(
  Effect.gen(function*() {
    const fileLogger = yield* Logger.formatJson.pipe(
      Logger.toFile("/tmp/app.log")
    )

    yield* Effect.log("Application started").pipe(
      Effect.provide(Logger.layer([fileLogger]))
    )
  })
).pipe(
  Effect.provide(NodeFileSystem.layer)
)

// File logger with custom batch window
const batchedFileLogger = Effect.scoped(
  Effect.gen(function*() {
    const fileLogger = yield* Logger.formatLogFmt.pipe(
      Logger.toFile("/var/log/myapp.log", {
        flag: "a",
        batchWindow: Duration.seconds(5)
      })
    )

    yield* Effect.all([
      Effect.log("Event 1"),
      Effect.log("Event 2"),
      Effect.log("Event 3")
    ]).pipe(
      Effect.provide(Logger.layer([fileLogger]))
    )
  })
).pipe(
  Effect.provide(NodeFileSystem.layer)
)

// Multiple loggers: console + file
const multiLogger = Effect.scoped(
  Effect.gen(function*() {
    const fileLogger = yield* Logger.formatJson.pipe(
      Logger.toFile("/tmp/production.log")
    )

    const loggerLive = Logger.layer([
      Logger.consolePretty(),
      fileLogger
    ])

    yield* Effect.log("Production event").pipe(
      Effect.provide(loggerLive)
    )
  })
).pipe(
  Effect.provide(NodeFileSystem.layer)
)
```

Returns a new `Logger` that writes all output of the specified `Logger` to
the console using `console.log`.

**When to use**

Use when a logger's string or object output should be routed to `console.log` for
development or debugging.

**Example** (Writing logger output with console.log)

```ts
import { Effect, Logger } from "effect"

// Create a custom formatter
const customFormatter = Logger.make((options) =>
  `[${options.date.toISOString()}] ${options.logLevel}: ${options.message}`
)

// Route to console
const consoleLogger = Logger.withConsoleLog(customFormatter)

const program = Effect.log("Hello World").pipe(
  Effect.provide(Logger.layer([consoleLogger]))
)
```

Returns a new `Logger` that writes all output of the specified `Logger` to
the console using `console.error`.

**When to use**

Use when logger output should be routed to `console.error`, such as error logs that
should appear on stderr instead of stdout.

**Example** (Writing logger output with console.error)

```ts
import { Effect, Logger } from "effect"

// Create an error-specific formatter
const errorFormatter = Logger.make((options) =>
  `ERROR [${options.date.toISOString()}]: ${options.message}`
)

// Route to console.error
const errorLogger = Logger.withConsoleError(errorFormatter)

const program = Effect.logError("Database connection failed").pipe(
  Effect.provide(Logger.layer([errorLogger]))
)
```

Creates a `Layer` which will overwrite the current set of loggers with the
specified array of `loggers`.

**Details**

If the specified array of `loggers` should be _merged_ with the current set
of loggers (instead of overwriting them), set `mergeWithExisting` to `true`.

**Example** (Providing logger layers)

```ts
import { Effect, Logger } from "effect"

// Single logger layer
const JsonLoggerLive = Logger.layer([Logger.consoleJson])

// Multiple loggers layer
const MultiLoggerLive = Logger.layer([
  Logger.consoleJson,
  Logger.consolePretty(),
  Logger.formatStructured
])

// Merge with existing loggers
const AdditionalLoggerLive = Logger.layer(
  [Logger.consoleJson],
  { mergeWithExisting: true }
)

// Using multiple logger formats
const jsonLogger = Logger.consoleJson
const prettyLogger = Logger.consolePretty()

const CustomLoggerLive = Logger.layer([jsonLogger, prettyLogger])

const program = Effect.log("Application started").pipe(
  Effect.provide(CustomLoggerLive)
)
```

A logger that transforms a runtime log event into an output value.

**Details**

The runtime calls `log` with the message, level, cause, fiber, and timestamp
for each log event. Use `Logger.layer` to install one or more loggers for an
effect.

**Example** (Creating custom loggers)

```ts
import { Effect, Logger } from "effect"

// Create a custom logger that accepts unknown messages and returns void
const stringLogger = Logger.make<unknown, void>((options) => {
  console.log(`[${options.logLevel}] ${options.message}`)
})

// Create a logger that accepts any message type and returns a formatted string
const formattedLogger = Logger.make<unknown, string>((options) =>
  `${options.date.toISOString()} [${options.logLevel}] ${options.message}`
)

// Use the logger in an Effect program
const program = Effect.log("Hello World").pipe(
  Effect.provide(Logger.layer([stringLogger]))
)
```

signature:
export interface Logger<in Message, out Output> extends Pipeable {
  readonly [TypeId]: typeof TypeId
  log(options: Options<Message>): Output
}

description:
Information supplied to a `Logger` for a single log event.

**Details**

Includes the logged message, log level, cause, current fiber, and timestamp.

**Example** (Accessing logger options)

```ts
import { Effect, Logger } from "effect"

// Options interface provides all logging context
const detailedLogger = Logger.make((options) => {
  const output = {
    message: options.message,
    level: options.logLevel,
    timestamp: options.date.toISOString(),
    fiberId: options.fiber.id,
    hasCause: options.cause !== undefined
  }
  console.log(JSON.stringify(output))
})

const program = Effect.log("Processing request").pipe(
  Effect.provide(Logger.layer([detailedLogger]))
)
```

Determines if the first log level is more severe than the second.

**When to use**

Use to check whether one log level is strictly more severe than another.

**Details**

Returns `true` if `self` represents a more severe level than `that`.

**Example** (Checking higher severity)

```ts
import { LogLevel } from "effect"

// Check if Error is more severe than Info
console.log(LogLevel.isGreaterThan("Error", "Info")) // true
console.log(LogLevel.isGreaterThan("Debug", "Error")) // false

// Use with filtering
const isFatal = LogLevel.isGreaterThan("Fatal", "Warn")
const isError = LogLevel.isGreaterThan("Error", "Warn")
const isDebug = LogLevel.isGreaterThan("Debug", "Warn")
console.log(isFatal) // true
console.log(isError) // true
console.log(isDebug) // false

// Curried usage
const isMoreSevereThanInfo = LogLevel.isGreaterThan("Info")
console.log(isMoreSevereThanInfo("Error")) // true
console.log(isMoreSevereThanInfo("Debug")) // false
```

Determines if the first log level is more severe than or equal to the second.

**When to use**

Use to implement minimum log-level filtering by checking whether a message
level meets a threshold.

**Details**

Returns `true` if `self` represents a level that is more severe than or equal to `that`.

**Example** (Filtering by minimum log level)

```ts
import { Logger, LogLevel } from "effect"

// Check if level meets minimum threshold
console.log(LogLevel.isGreaterThanOrEqualTo("Error", "Error")) // true
console.log(LogLevel.isGreaterThanOrEqualTo("Error", "Info")) // true
console.log(LogLevel.isGreaterThanOrEqualTo("Debug", "Info")) // false

// Create a logger that only logs Info and above
const infoLogger = Logger.make((options) => {
  if (LogLevel.isGreaterThanOrEqualTo(options.logLevel, "Info")) {
    console.log(`[${options.logLevel}] ${options.message}`)
  }
})

// Production logger - only Error and Fatal
const productionLogger = Logger.make((options) => {
  if (LogLevel.isGreaterThanOrEqualTo(options.logLevel, "Error")) {
    console.error(
      `${options.date.toISOString()} [${options.logLevel}] ${options.message}`
    )
  }
})

// Curried usage for filtering
const isInfoOrAbove = LogLevel.isGreaterThanOrEqualTo("Info")
const shouldLog = isInfoOrAbove("Error") // true
```

Determines if the first log level is less severe than the second.

**When to use**

Use to check whether one log level is strictly less severe than another.

**Details**

Returns `true` if `self` represents a less severe level than `that`.

**Example** (Checking lower severity)

```ts
import { LogLevel } from "effect"

// Check if Debug is less severe than Info
console.log(LogLevel.isLessThan("Debug", "Info")) // true
console.log(LogLevel.isLessThan("Error", "Info")) // false

// Filter out verbose logs
const isFatalVerbose = LogLevel.isLessThan("Fatal", "Info")
const isErrorVerbose = LogLevel.isLessThan("Error", "Info")
const isTraceVerbose = LogLevel.isLessThan("Trace", "Info")
console.log(isFatalVerbose) // false (Fatal is not verbose)
console.log(isErrorVerbose) // false (Error is not verbose)
console.log(isTraceVerbose) // true (Trace is verbose)

// Curried usage
const isLessSevereThanError = LogLevel.isLessThan("Error")
console.log(isLessSevereThanError("Info")) // true
console.log(isLessSevereThanError("Fatal")) // false
```

Determines if the first log level is less severe than or equal to the second.

**When to use**

Use to implement maximum log-level filtering by checking whether a level is
at or below a threshold.

**Details**

Returns `true` if `self` represents a level that is less severe than or equal to `that`.

**Example** (Filtering by maximum log level)

```ts
import { Logger, LogLevel } from "effect"

// Check if level is at or below threshold
console.log(LogLevel.isLessThanOrEqualTo("Info", "Info")) // true
console.log(LogLevel.isLessThanOrEqualTo("Debug", "Info")) // true
console.log(LogLevel.isLessThanOrEqualTo("Error", "Info")) // false

// Create a logger that suppresses verbose logs
const quietLogger = Logger.make((options) => {
  if (LogLevel.isLessThanOrEqualTo(options.logLevel, "Info")) {
    console.log(`[${options.logLevel}] ${options.message}`)
  }
})

// Development logger - suppress trace logs
const devLogger = Logger.make((options) => {
  if (LogLevel.isLessThanOrEqualTo(options.logLevel, "Debug")) {
    console.log(`[${options.logLevel}] ${options.message}`)
  }
})

// Curried usage for filtering
const isInfoOrBelow = LogLevel.isLessThanOrEqualTo("Info")
const shouldLog = isInfoOrBelow("Debug") // true
```

Checks whether a given log level is enabled for the current fiber.

**When to use**

Use to check whether a log level would be emitted under the current fiber's
minimum log level.

**Details**

A log level is enabled when it is greater than or equal to
`References.MinimumLogLevel`.

**Example** (Checking current fiber log level)

```ts
import { Effect, LogLevel, References } from "effect"

const program = Effect.gen(function*() {
  const debugEnabled = yield* LogLevel.isEnabled("Debug")
  const errorEnabled = yield* LogLevel.isEnabled("Error")

  console.log({ debugEnabled, errorEnabled })
})

const warnOnly = program.pipe(
  Effect.provideService(References.MinimumLogLevel, "Warn")
)
```

Creates a `ManagedRuntime` from a layer.

**When to use**

Use to create a reusable runtime from a `Layer` for application entry points
or integration code that runs many effects without rebuilding services.

**Details**

The layer is built lazily on first use and its context is cached for
subsequent runs. Resources acquired by the layer are owned by the runtime and
are released when `dispose` or `disposeEffect` is run. `options.memoMap` can
be used to share layer memoization with other layer builds.

**Gotchas**

Dispose the runtime when it is no longer needed. A runtime cannot be reused
after disposal.

**Example** (Creating a managed runtime)

```ts
import { Context, Effect, Layer, ManagedRuntime } from "effect"

class Notifications extends Context.Service<Notifications, {
  readonly notify: (message: string) => Effect.Effect<void>
}>()("Notifications") {
  static readonly layer = Layer.succeed(this)({
    notify: Effect.fn("Notifications.notify")((message) =>
      Effect.sync(() => console.log(message))
    )
  })
}

const runtime = ManagedRuntime.make(Notifications.layer)

const program = Effect.flatMap(
  Notifications,
  (_) => _.notify("Hello, world!")
).pipe(Effect.ensuring(runtime.disposeEffect))

runtime.runPromise(program)
// Hello, world!
```

Creates a matcher for a specific type.

**When to use**

Use to build a reusable matcher function for values of a known input type.

**Details**

This function defines a `Matcher` that operates on a given type, allowing you
to specify conditions for handling different cases. Once the matcher is
created, you can use pattern-matching functions like {@link when} to define
how different values should be processed.

**Example** (Matching Numbers and Strings)

```ts
import { Match } from "effect"

// Create a matcher for values that are either strings or numbers
//
//      ┌─── (u: string | number) => string
//      ▼
const match = Match.type<string | number>().pipe(
  // Match when the value is a number
  Match.when(Match.number, (n) => `number: ${n}`),
  // Match when the value is a string
  Match.when(Match.string, (s) => `string: ${s}`),
  // Ensure all possible cases are handled
  Match.exhaustive
)

console.log(match(0))
// Output: "number: 0"

console.log(match("hello"))
// Output: "string: hello"
```

Creates a match function for a specific value with discriminated union handling.

**Details**

This function provides a convenient way to pattern match on discriminated unions
by providing an object that maps each `_tag` value to its corresponding handler.
It's similar to a switch statement but with better type safety and exhaustiveness checking.

**Example** (Matching value tags)

```ts
import { Match } from "effect"

type Status = { readonly _tag: "Success"; readonly data: string }

const success: Status = { _tag: "Success", data: "Hello" }

// Simple valueTags usage
const message = Match.valueTags(success, {
  Success: (result) => `Success: ${result.data}`
})

console.log(message) // "Success: Hello"
```

Creates a type-safe match function for discriminated unions based on `_tag` field.

**Details**

This function allows you to define exhaustive pattern matching for discriminated unions
by providing handlers for each possible `_tag` value. It ensures type safety and
can optionally enforce a specific return type across all branches.

**Example** (Matching type tags)

```ts
import { Match } from "effect"

type Result =
  | { readonly _tag: "Success"; readonly data: string }
  | { readonly _tag: "Error"; readonly message: string }
  | { readonly _tag: "Loading" }

// Create a matcher with specific return type
const formatResult = Match.typeTags<Result, string>()({
  Success: (result) => `Data: ${result.data}`,
  Error: (result) => `Error: ${result.message}`,
  Loading: () => "Loading..."
})

console.log(formatResult({ _tag: "Success", data: "Hello World" }))
// Output: "Data: Hello World"

console.log(formatResult({ _tag: "Error", message: "Network failed" }))
// Output: "Error: Network failed"

// Create a matcher with inferred return type
const processResult = Match.typeTags<Result>()({
  Success: (result) => ({ type: "ok", value: result.data }),
  Error: (result) => ({ type: "error", error: result.message }),
  Loading: () => ({ type: "pending" })
})

console.log(processResult({ _tag: "Loading" }))
// Output: { type: "pending" }
```

Defines a condition for matching values.

**When to use**

Use to add one positive pattern case to a `Match.type` or `Match.value`
pipeline when a direct value, predicate, or structured object pattern should
run a handler for matching input.

**Details**

Supports both direct value comparisons and predicate functions. If the
pattern matches, the associated function is executed and the matched input is
removed from the remaining cases tracked by the matcher.

**Example** (Matching with values and predicates)

```ts
import { Match } from "effect"

// Create a matcher for objects with an "age" property
const match = Match.type<{ age: number }>().pipe(
  // Match when age is greater than 18
  Match.when(
    { age: (age: number) => age > 18 },
    (user: { age: number }) => `Age: ${user.age}`
  ),
  // Match when age is exactly 18
  Match.when({ age: 18 }, () => "You can vote"),
  // Fallback case for all other ages
  Match.orElse((user: { age: number }) => `${user.age} is too young`)
)

console.log(match({ age: 20 }))
// Output: "Age: 20"

console.log(match({ age: 18 }))
// Output: "You can vote"

console.log(match({ age: 4 }))
// Output: "4 is too young"
```

Matches discriminated union members by their `_tag` field.

**When to use**

Use to handle one or more `_tag` cases with the same matcher branch.

**Details**

This helper follows the Effect convention that discriminated unions use
`"_tag"` as their discriminator field. Use {@link discriminator} for a
different discriminator field.

**Example** (Matching a discriminated union by tag)

```ts
import { Match } from "effect"

type Event =
  | { readonly _tag: "fetch" }
  | { readonly _tag: "success"; readonly data: string }
  | { readonly _tag: "error"; readonly error: Error }
  | { readonly _tag: "cancel" }

const match = Match.type<Event>().pipe(
  // Match either "fetch" or "success"
  Match.tag("fetch", "success", () => `Ok!`),
  // Match "error" and extract the error message
  Match.tag("error", (event) => `Error: ${event.error.message}`),
  // Match "cancel"
  Match.tag("cancel", () => "Cancelled"),
  Match.exhaustive
)

console.log(match({ _tag: "success", data: "Hello" }))
// Output: "Ok!"

console.log(match({ _tag: "error", error: new Error("Oops!") }))
// Output: "Error: Oops!"
```

Creates a pattern that excludes a specific value while allowing all others.

**When to use**

Use to add a negative pattern case for inputs that should match when another
pattern does not.

**Details**

Any excluded value bypasses the provided function and continues matching
through later cases.

**Example** (Ignoring a specific value)

```ts
import { Match } from "effect"

// Create a matcher for string or number values
const match = Match.type<string | number>().pipe(
  // Match any value except "hi", returning "ok"
  Match.not("hi", () => "ok"),
  // Fallback case for when the value is "hi"
  Match.orElse(() => "fallback")
)

console.log(match("hello"))
// Output: "ok"

console.log(match("hi"))
// Output: "fallback"
```

Matches values of type `symbol`.

**Details**

This predicate refines unknown values to symbols, allowing pattern matching
on symbol types. Symbols are unique identifiers that are often used as
object keys or for creating private properties.

**Example** (Matching symbol values)

```ts
import { Match } from "effect"

const mySymbol = Symbol("my-symbol")
const globalSymbol = Symbol.for("global-symbol")

const handleSymbol = Match.type<unknown>().pipe(
  Match.when(Match.symbol, (sym) => {
    const description = sym.description
    if (description) {
      return `Symbol with description: ${description}`
    }
    return "Symbol without description"
  }),
  Match.orElse(() => "Not a symbol")
)

console.log(handleSymbol(mySymbol)) // "Symbol with description: my-symbol"
console.log(handleSymbol(Symbol())) // "Symbol without description"
console.log(handleSymbol("string")) // "Not a symbol"
```

Checks whether a value is an instance of a constructor without type-safe narrowing.

**When to use**

Use when you need constructor matching to use the unsafe refinement type.

**Details**

This predicate checks if a value is an instance of the specified constructor
but doesn't provide the same type safety guarantees as the regular `instanceOf`.
Use this when you need more flexibility but understand the type safety implications.

**Example** (Matching class instances unsafely)

```ts
import { Match } from "effect"

class CustomError extends Error {
  constructor(message: string, public code: number) {
    super(message)
  }
}

// When you need to match instances but handle type narrowing manually
const handleError = Match.type<unknown>().pipe(
  Match.when(Match.instanceOfUnsafe(CustomError), (err: any) => {
    // Manual type assertion needed
    const customErr = err as CustomError
    return `Custom error ${customErr.code}: ${customErr.message}`
  }),
  Match.orElse(() => "Not a CustomError")
)
```

Provides a fallback value when no patterns match.

**When to use**

Use to finalize a matcher with a fallback for unmatched input.

**Details**

This function ensures that a matcher always returns a valid result, even if
no defined patterns match. It acts as a default case, similar to the
`default` clause in a `switch` statement or the final `else` in an `if-else`
chain.

**Example** (Providing a default value when no patterns match)

```ts
import { Match } from "effect"

// Create a matcher for string or number values
const match = Match.type<string | number>().pipe(
  // Match when the value is "a"
  Match.when("a", () => "ok"),
  // Fallback when no patterns match
  Match.orElse(() => "fallback")
)

console.log(match("a"))
// Output: "ok"

console.log(match("b"))
// Output: "fallback"
```

Wraps the match result in a `Result`, distinguishing matched and unmatched
cases.

**Details**

This function ensures that the result of a matcher is always wrapped in an
`Result`, allowing clear differentiation between successful matches
(`Ok(value)`) and cases where no pattern matched (`Err(unmatched
value)`).

This approach is particularly useful when handling optional values or when an
unmatched case should be explicitly handled rather than returning a default
value or throwing an error.

**Example** (Extracting a user role with `Match.result`)

```ts
import { Match } from "effect"

type User = { readonly role: "admin" | "editor" | "viewer" }

// Create a matcher to extract user roles
const getRole = Match.type<User>().pipe(
  Match.when({ role: "admin" }, () => "Has full access"),
  Match.when({ role: "editor" }, () => "Can edit content"),
  Match.result // Wrap the result in an Result
)

console.log(getRole({ role: "admin" }))
// Output: { _id: 'Result', _tag: 'Ok', ok: 'Has full access' }

console.log(getRole({ role: "viewer" }))
// Output: { _id: 'Result', _tag: 'Err', err: { role: 'viewer' } }
```

Wraps the match result in an `Option`, representing an optional match.

**When to use**

Use to finalize a matcher when unmatched input is expected and should become
`Option.none`.

**Details**

This function ensures that the result of a matcher is wrapped in an `Option`,
making it easy to handle cases where no pattern matches. If a match is found,
it returns `Some(value)`, otherwise, it returns `None`.

This is useful in cases where a missing match is expected and should be
handled explicitly rather than throwing an error or returning a default
value.

**Example** (Extracting a user role with `Match.option`)

```ts
import { Match } from "effect"

type User = { readonly role: "admin" | "editor" | "viewer" }

// Create a matcher to extract user roles
const getRole = Match.type<User>().pipe(
  Match.when({ role: "admin" }, () => "Has full access"),
  Match.when({ role: "editor" }, () => "Can edit content"),
  Match.option // Wrap the result in an Option
)

console.log(getRole({ role: "admin" }))
// Output: { _id: 'Option', _tag: 'Some', value: 'Has full access' }

console.log(getRole({ role: "viewer" }))
// Output: { _id: 'Option', _tag: 'None' }
```

Completes a matcher that handles every remaining input case.

**When to use**

Use to require TypeScript to reject incomplete matcher definitions before the
matcher is turned into a function.

**Details**

If any case is still unmatched, the matcher does not type-check as
exhaustive.

**Example** (Ensuring all cases are covered)

```ts
import { Match } from "effect"

// Create a matcher for string or number values
const match = Match.type<string | number>().pipe(
  // Match when the value is a number
  Match.when(Match.number, (n) => `number: ${n}`),
  // Mark the match as exhaustive, ensuring all cases are handled
  // TypeScript will throw an error if any case is missing
  // @ts-expect-error Type 'string' is not assignable to type 'never'
  Match.exhaustive
)
```

signature:
export interface TypeMatcher<in Input, out Filters, out Remaining, out Result, out Return = any> extends Pipeable {
  readonly _tag: "TypeMatcher"
  readonly [TypeId]: {
    readonly _input: T.Contravariant<Input>
    readonly _filters: T.Covariant<Filters>
    readonly _remaining: T.Covariant<Remaining>
    readonly _result: T.Covariant<Result>
    readonly _return: T.Covariant<Return>
  }
  readonly cases: ReadonlyArray<Case>
  add<I, R, RA, A>(_case: Case): TypeMatcher<I, R, RA, A>
}

export interface When {
  readonly _tag: "When"
  guard(u: unknown): boolean
  evaluate(input: unknown): any
}

export interface Not {
  readonly _tag: "Not"
  guard(u: unknown): boolean
  evaluate(input: unknown): any
}

export interface SafeRefinement<in A, out R = A> {
  readonly [SafeRefinementId]: (a: A) => R
}

description:
Union type for matchers created by `Match.type` and `Match.value`.

**Details**

A `Matcher` carries the input type, accumulated filters, remaining cases,
result type, and, for value matchers, the provided value being matched.

**Example** (Matching string and number values)

```ts
import { Match } from "effect"

// Simulated dynamic input that can be a string or a number
const input: string | number = "some input"

//      ┌─── string
//      ▼
const result = Match.value(input).pipe(
  // Match if the value is a number
  Match.when(Match.number, (n) => `number: ${n}`),
  // Match if the value is a string
  Match.when(Match.string, (s) => `string: ${s}`),
  // Ensure all possible cases are covered
  Match.exhaustive
)

console.log(result)
// Output: "string: some input"
```

signature:
export interface Without<out X> {
    readonly _tag: "Without"
    readonly _X: X
  }

export interface Only<out X> {
    readonly _tag: "Only"
    readonly _X: X
