export interface Any {
  readonly [TypeId]: typeof TypeId
  readonly tools: Record<string, Tool.Any>
}

type ToolsByName<Tools> = Tools extends Record<string, Tool.Any> ?
  { readonly [Name in keyof Tools]: Tools[Name] }
  : Tools extends ReadonlyArray<Tool.Any> ? { readonly [Tool in Tools[number] as Tool["name"]]: Tool }
  : never

type HandlersFrom<Tools> = {
  readonly [Name in keyof Tools as Tool.RequiresHandler<Tools[Name]> extends true ? Name : never]: (
    params: Tool.Parameters<Tools[Name]>,
    context: HandlerContext<Tools[Name]>
  ) => Effect.Effect<
    Tool.Success<Tools[Name]>,
    Tool.Failure<Tools[Name]> | AiError.AiError | AiError.AiErrorReason,
    Tool.HandlerServices<Tools[Name]>
  >
}

type MergeRecords<U> = {
  readonly [K in Extract<U extends unknown ? keyof U : never, string>]: Extract<
    U extends Record<K, infer V> ? V : never,
    Tool.Any
  >
}

description:
Creates a variadic positional argument that accepts multiple values.

**Example** (Accepting multiple values)

```ts
import { Argument } from "effect/unstable/cli"

// Accept any number of files
const anyFiles = Argument.string("files").pipe(Argument.variadic)

// Accept at least 1 file
const atLeastOneFile = Argument.string("files").pipe(
  Argument.variadic({ min: 1 })
)

// Accept between 1 and 5 files
const limitedFiles = Argument.string("files").pipe(
  Argument.variadic({ min: 1, max: 5 })
)
```

Transforms the parsed value of a positional argument using an effectful function.

**Example** (Validating values effectfully)

```ts
import { Effect } from "effect"
import { Argument, CliError } from "effect/unstable/cli"

const files = Argument.string("files").pipe(
  Argument.mapEffect((file) =>
    file.endsWith(".txt")
      ? Effect.succeed(file)
      : Effect.fail(
        new CliError.UserError({
          cause: new Error("Only .txt files allowed")
        })
      )
  )
)
```

Provides a fallback argument, wrapping results in Result to distinguish which succeeded.

**Example** (Returning which fallback succeeded)

```ts
import { Argument } from "effect/unstable/cli"

const source = Argument.file("source").pipe(
  Argument.orElseResult(() => Argument.string("url"))
)
// Returns Result<string, string>
```

Error thrown when an unrecognized option is encountered.

**Example** (Creating unrecognized option errors)

```ts
import { Effect } from "effect"
import { CliError } from "effect/unstable/cli"

// Creating an unrecognized option error
const unrecognizedError = new CliError.UnrecognizedOption({
  option: "--unknown-flag",
  command: ["deploy", "production"],
  suggestions: ["--verbose", "--force"]
})

console.log(unrecognizedError.message)
// "Unrecognized flag: --unknown-flag in command deploy production
//
//  Did you mean this?
//    --verbose
//    --force"

// In CLI parsing context
const parseCommand = Effect.gen(function*() {
  // If parsing encounters unknown flag
  return yield* unrecognizedError
})
```

Error thrown when duplicate option names are detected between parent and child commands.

**Example** (Creating duplicate option errors)

```ts
import { CliError } from "effect/unstable/cli"

const duplicateError = new CliError.DuplicateOption({
  option: "--verbose",
  parentCommand: "myapp",
  childCommand: "deploy"
})

console.log(duplicateError.message)
// "Duplicate flag name "--verbose" in parent command "myapp" and subcommand "deploy".
// Parent will always claim this flag (Mode A semantics). Consider renaming one of them to avoid confusion."
```

Error thrown when a required option is missing.

**Example** (Creating missing option errors)

```ts
import { Effect } from "effect"
import { CliError } from "effect/unstable/cli"

const missingOptionError = new CliError.MissingOption({
  option: "api-key"
})

console.log(missingOptionError.message)
// "Missing required flag: --api-key"

// In validation context
const validateRequiredOptions = (options: Record<string, string | undefined>) =>
  Effect.gen(function*() {
    const apiKey = options["api-key"]
    if (!apiKey) {
      return yield* missingOptionError
    }
    return apiKey
  })
```

Error thrown when a required positional argument is missing.

**Example** (Creating missing argument errors)

```ts
import { Effect } from "effect"
import { CliError } from "effect/unstable/cli"

const missingArgError = new CliError.MissingArgument({
  argument: "target"
})

console.log(missingArgError.message)
// "Missing required argument: target"

// In argument parsing
const parseArguments = (args: Array<string>) =>
  Effect.gen(function*() {
    if (args.length === 0) {
      return yield* missingArgError
    }
    return args[0]
  })
```

Error thrown when an option or argument value is invalid.

**Example** (Creating invalid value errors)

```ts
import { Effect } from "effect"
import { CliError } from "effect/unstable/cli"

const invalidValueError = new CliError.InvalidValue({
  option: "port",
  value: "abc123",
  expected: "integer between 1 and 65535",
  kind: "flag"
})

console.log(invalidValueError.message)
// "Invalid value for flag --port: "abc123". Expected: integer between 1 and 65535"

// For positional arguments
const invalidArgError = new CliError.InvalidValue({
  option: "count",
  value: "abc",
  expected: "integer",
  kind: "argument"
})

console.log(invalidArgError.message)
// "Invalid value for argument <count>: "abc". Expected: integer"
```

Error thrown when an unknown subcommand is encountered.

**Example** (Creating unknown subcommand errors)

```ts
import { Effect } from "effect"
import { CliError } from "effect/unstable/cli"

const unknownSubcommandError = new CliError.UnknownSubcommand({
  subcommand: "deplyo", // typo
  parent: ["myapp"],
  suggestions: ["deploy", "destroy"]
})

console.log(unknownSubcommandError.message)
// "Unknown subcommand "deplyo" for "myapp"
//
//  Did you mean this?
//    deploy
//    destroy"

// In subcommand parsing
const parseSubcommand = (subcommand: string) =>
  Effect.gen(function*() {
    const validCommands = ["deploy", "destroy", "status"]
    if (!validCommands.includes(subcommand)) {
      return yield* unknownSubcommandError
    }
    return subcommand
  })
```

Error wrapper for user handler failures in the CLI error channel.

**Example** (Wrapping user errors)

```ts
import { Effect } from "effect"
import { CliError } from "effect/unstable/cli"

// Wrapping user errors
const userError = new CliError.UserError({
  cause: new Error("Database connection failed")
})

// In command handler
const deployCommand = Effect.gen(function*() {
  const result = yield* Effect.try({
    try: () => ({ deployed: true }),
    catch: (error) => new CliError.UserError({ cause: error })
  })
  return result
})

// In error handling
const handleError = (error: CliError.CliError): Effect.Effect<number> => {
  if (error._tag === "UserError") {
    console.log("Command failed:", error.cause)
    return Effect.succeed(1) // Exit code 1
  }
  return Effect.succeed(0)
}
```

Type guard to check if a value is a CLI error.

**Example** (Checking CLI errors)

```ts
import { Effect } from "effect"
import { CliError } from "effect/unstable/cli"

const handleError = (error: unknown) => {
  if (CliError.isCliError(error)) {
    console.log("CLI Error:", error.message)
    return Effect.succeed("Handled CLI error")
  }
  return Effect.fail("Unknown error")
}

// Example usage in error handling
const program = Effect.gen(function*() {
  const result = yield* Effect.try({
    try: () => ({ success: true }),
    catch: (error) => error
  })
  handleError(result)
})
```

Service reference for the CLI output formatter. Provides a default implementation
that can be overridden for custom formatting or testing.

**Example** (Accessing the output formatter)

```ts
import { Effect } from "effect"
import { CliOutput } from "effect/unstable/cli"

// Access the formatter service
const program = Effect.gen(function*() {
  const formatter = yield* CliOutput.Formatter

  // Format version information
  const versionText = formatter.formatVersion("my-cli", "2.1.0")
  console.log(versionText) // "my-cli v2.1.0" (with colors if supported)

  return versionText
})

// Run with default formatter
const result = Effect.runSync(program)
```

Creates a Layer that provides a custom Formatter implementation.

**Example** (Providing a custom formatter)

```ts
import { Console, Effect } from "effect"
import { CliOutput } from "effect/unstable/cli"

// Create a custom formatter without colors
const noColorFormatter = CliOutput.defaultFormatter({ colors: false })
const NoColorLayer = CliOutput.layer(noColorFormatter)

// Create a program that uses the custom formatter
const program = Effect.gen(function*() {
  const formatter = yield* CliOutput.Formatter
  const versionText = formatter.formatVersion("my-cli", "1.0.0")
  yield* Console.log(`Using custom formatter: ${versionText}`)
}).pipe(
  Effect.provide(NoColorLayer)
)

// You can also create completely custom formatters
const jsonFormatter: CliOutput.Formatter = {
  formatHelpDoc: (doc) => JSON.stringify(doc, null, 2),
  formatCliError: (error) => JSON.stringify({ error: error.message }),
  formatError: (error) =>
    JSON.stringify({ type: "error", message: error.message }),
  formatVersion: (name, version) => JSON.stringify({ name, version }),
  formatErrors: (errors) => JSON.stringify(errors.map((error) => error.message))
}
const JsonLayer = CliOutput.layer(jsonFormatter)
```

Creates a default formatter with configurable options.

**Example** (Creating default formatters)

```ts
import { Effect } from "effect"
import { CliError, CliOutput } from "effect/unstable/cli"

// Create a formatter without colors for tests or CI environments
const noColorFormatter = CliOutput.defaultFormatter({ colors: false })

// Create a formatter with colors forced on
const colorFormatter = CliOutput.defaultFormatter({ colors: true })

// Auto-detect colors based on terminal support (default behavior)
const autoFormatter = CliOutput.defaultFormatter()

const program = Effect.gen(function*() {
  const formatter = colorFormatter

  // Format an error with proper styling
  const error = new CliError.InvalidValue({
    option: "foo",
    value: "bar",
    expected: "baz",
    kind: "flag"
  })
  const errorText = formatter.formatError(error)
  console.log(errorText)

  // Format version information
  const versionText = formatter.formatVersion("my-tool", "1.2.3")
  console.log(versionText)
})
```

Defines the service interface for formatting CLI output including help, errors, and version info.
This allows customization of output formatting, including color support.

**Example** (Customizing CLI output formatting)

```ts
import { Effect } from "effect"
import { CliOutput } from "effect/unstable/cli"

// Create a custom formatter implementation
const customFormatter: CliOutput.Formatter = {
  formatHelpDoc: (doc) => `Custom Help: ${doc.usage}`,
  formatCliError: (error) => `Error: ${error.message}`,
  formatError: (error) => `[ERROR] ${error.message}`,
  formatVersion: (name, version) => `${name} (${version})`,
  formatErrors: (errors) => errors.map((error) => error.message).join("\\n")
}

// Use the custom formatter in a program
const program = Effect.gen(function*() {
  const formatter = yield* CliOutput.Formatter
  const helpText = formatter.formatVersion("myapp", "1.0.0")
  console.log(helpText)
}).pipe(
  Effect.provide(CliOutput.layer(customFormatter))
)
```

Creates a `Command` from a name, an optional configuration, and an optional
handler.

**Details**

Use `withDescription` and related metadata combinators to add help text. The
overloads support simple commands, configured commands, and commands with
effectful handlers.

**Example** (Creating commands)

```ts
import { Console, Effect } from "effect"
import { Argument, Command, Flag } from "effect/unstable/cli"

// Simple command with no configuration
const version = Command.make("version")

// Command with simple flags
const greet = Command.make("greet", {
  name: Flag.string("name"),
  count: Flag.integer("count").pipe(Flag.withDefault(1))
})

// Command with nested configuration
const deploy = Command.make("deploy", {
  environment: Flag.string("env").pipe(
    Flag.withDescription("Target environment")
  ),
  server: {
    host: Flag.string("host").pipe(Flag.withDefault("localhost")),
    port: Flag.integer("port").pipe(Flag.withDefault(3000))
  },
  files: Argument.string("files").pipe(Argument.variadic),
  force: Flag.boolean("force").pipe(Flag.withDescription("Force deployment"))
})

// Command with handler
const deployWithHandler = Command.make("deploy", {
  environment: Flag.string("env"),
  force: Flag.boolean("force")
}, (config) =>
  Effect.gen(function*() {
    yield* Console.log(`Starting deployment to ${config.environment}`)

    if (!config.force && config.environment === "production") {
      return yield* Effect.fail("Production deployments require --force flag")
    }

    yield* Console.log("Deployment completed successfully")
  }))
```

Adds or replaces the handler for a command.

**Example** (Adding command handlers)

```ts
import { Console } from "effect"
import { Command, Flag } from "effect/unstable/cli"

// Command without initial handler
const greet = Command.make("greet", {
  name: Flag.string("name")
})

// Add handler later
const greetWithHandler = greet.pipe(
  Command.withHandler((config: { readonly name: string }) =>
    Console.log(`Hello, ${config.name}!`)
  )
)
```

Adds subcommands to a command, creating a hierarchical command structure.

**Details**

Subcommands can access their parent's parsed configuration by yielding the parent
command within their handler. This enables shared parent flags that affect
all subcommands.

**Example** (Adding subcommands)

```ts
import { Console, Effect } from "effect"
import { Command, Flag } from "effect/unstable/cli"

// Parent command with shared flags
const git = Command.make("git").pipe(
  Command.withSharedFlags({
    verbose: Flag.boolean("verbose")
  })
)

// Subcommand that accesses parent config
const clone = Command.make("clone", {
  repository: Flag.string("repo")
}, (config) =>
  Effect.gen(function*() {
    const parent = yield* git // Access parent's parsed config
    if (parent.verbose) {
      yield* Console.log("Verbose mode enabled")
    }
    yield* Console.log(`Cloning ${config.repository}`)
  }))

const app = git.pipe(Command.withSubcommands([clone]))
// Usage: git --verbose clone --repo github.com/foo/bar
```

Provides the handler of a command with the services produced by a layer
that optionally depends on the command-line input to be created.

**Example** (Providing command services)

```ts
import { Effect, FileSystem, PlatformError } from "effect"
import { Command, Flag } from "effect/unstable/cli"

const deploy = Command.make("deploy", {
  env: Flag.string("env")
}, (config) =>
  Effect.gen(function*() {
    const fs = yield* FileSystem.FileSystem
    // Use fs...
  })).pipe(
    // Provide FileSystem based on the --env flag
    Command.provide((config) =>
      config.env === "local"
        ? FileSystem.layerNoop({})
        : FileSystem.layerNoop({
          access: () =>
            Effect.fail(
              PlatformError.badArgument({
                module: "FileSystem",
                method: "access"
              })
            )
        })
    )
  )
```

Runs a command using the arguments supplied by the `Stdio` service.

**When to use**

Use when command-line arguments should come from `Stdio` at the application
entry point.

**Example** (Running commands with standard input)

```ts
import { Console, Effect } from "effect"
import { Command, Flag } from "effect/unstable/cli"

const greetCommand = Command.make("greet", {
  name: Flag.string("name")
}, (config) =>
  Effect.gen(function*() {
    yield* Console.log(`Hello, ${config.name}!`)
  }))

// Automatically gets args from the Stdio service
const program = Command.run(greetCommand, {
  version: "1.0.0"
})
```

Hides a subcommand from parent help output, shell completions, and
"did you mean?" suggestions while keeping it fully invocable by exact name.

**When to use**

Use when experimental or internal subcommands should be accepted but not advertised on
the public CLI surface.

**Example** (Hiding a subcommand)

```ts
import { Command } from "effect/unstable/cli"

// `experimental` still runs when invoked as `mycli experimental`,
// but it does not appear under SUBCOMMANDS in `mycli --help`.
const experimental = Command.make("experimental").pipe(
  Command.withHidden
)

const root = Command.make("mycli").pipe(
  Command.withSubcommands([experimental])
)
```

Runs a command with explicitly provided arguments instead of using arguments from `Stdio`.

**When to use**

Use when you need to test CLI applications or programmatically execute
commands with specific arguments.

**Example** (Running commands with explicit arguments)

```ts
import { Console, Effect } from "effect"
import { Command, Flag } from "effect/unstable/cli"

const greet = Command.make("greet", {
  name: Flag.string("name"),
  count: Flag.integer("count").pipe(Flag.withDefault(1))
}, (config) =>
  Effect.gen(function*() {
    for (let i = 0; i < config.count; i++) {
      yield* Console.log(`Hello, ${config.name}!`)
    }
  }))

// Test with specific arguments
const testProgram = Effect.gen(function*() {
  const runCommand = Command.runWith(greet, { version: "1.0.0" })

  // Test normal execution
  yield* runCommand(["--name", "Alice", "--count", "2"])

  // Test help display
  yield* runCommand(["--help"])

  // Test version display
  yield* runCommand(["--version"])
})
```

Represents a CLI command with its configuration, handler, and metadata.

**Details**

Commands are the core building blocks of CLI applications. They define:

- The command name and description
- Configuration including flags and arguments
- Handler function for execution
- Optional subcommands for hierarchical structures

**Example** (Defining CLI commands)

```ts
import { Console } from "effect"
import { Argument, Command, Flag } from "effect/unstable/cli"

// Simple command with no configuration
const version: Command.Command<"version", {}, {}, never, never> = Command.make(
  "version"
)

// Command with flags and arguments
const deploy: Command.Command<
  "deploy",
  {
    readonly env: string
    readonly force: boolean
    readonly files: ReadonlyArray<string>
  },
  {},
  never,
  never
> = Command.make("deploy", {
  env: Flag.string("env"),
  force: Flag.boolean("force"),
  files: Argument.string("files").pipe(Argument.variadic())
})

// Command with handler
const greet = Command.make("greet", {
  name: Flag.string("name")
}, (config) => Console.log(`Hello, ${config.name}!`))
```

Service context for a specific command, enabling subcommands to access their parent's parsed configuration.

**Details**

When a subcommand handler needs access to flags or arguments from a parent command,
it can yield the parent command directly to retrieve its config. This is powered by
Effect's service system - each command automatically creates a service that provides
its parsed input to child commands.

**Example** (Accessing parent command context)

```ts
import { Console, Effect } from "effect"
import { Command, Flag } from "effect/unstable/cli"

const parent = Command.make("app").pipe(
  Command.withSharedFlags({
    verbose: Flag.boolean("verbose"),
    config: Flag.string("config")
  })
)

const child = Command.make("deploy", {
  target: Flag.string("target")
}, (config) =>
  Effect.gen(function*() {
    // Access parent's config by yielding the parent command
    const parentConfig = yield* parent
    yield* Console.log(`Verbose: ${parentConfig.verbose}`)
    yield* Console.log(`Config: ${parentConfig.config}`)
    yield* Console.log(`Target: ${config.target}`)
  }))

const app = parent.pipe(Command.withSubcommands([child]))
// Usage: app --verbose --config prod.json deploy --target staging
```

